def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_by(items, scorer, want_min=True):
        best_item = None
        best_score = None
        for item in items:
            try:
                s = scorer(item)
            except Exception:
                continue
            if best_item is None or (want_min and s < best_score) or ((not want_min) and s > best_score):
                best_item, best_score = item, s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_by(corners, lambda c: dist(c, opp_p), want_min=False)
        if target is None:
            target = (sx, sy)
        move = step_away(self_p, opp_p)
        if move == [0, 0]:
            move = step_toward(self_p, target)
        return move

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "targets"):
            vals = observation.get(key) or []
            if vals:
                candidates.extend(vals)
        target = best_by(candidates, lambda c: dist(pos(c), self_p), want_min=True)
        if target is not None:
            tp = pos(target)
            return step_toward(self_p, tp)
        # fallback: pressure opponent or drift toward center
        if w and h:
            center = (w // 2, h // 2)
            if dist(self_p, center) >= dist(opp_p, center):
                return step_toward(self_p, center)
        return step_toward(self_p, opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = best_by(resources, lambda c: dist(pos(c), self_p), want_min=True)
        if target is not None:
            return step_toward(self_p, pos(target))

    # Deny opponent / default robust movement
